import java.beans.Introspector;
import java.lang.reflect.Method;

import org.springframework.beans.BeanWrapper;
import org.springframework.beans.BeanWrapperImpl;

public final class BeanMergeUtils {

	private BeanMergeUtils() {
	}

	public static <I, T, S extends T> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz) {
		if (source == null || target == null || sourceInterfaceClazz == null) {
			return target;
		}

		BeanWrapper sourceWrapper = new BeanWrapperImpl(source);
		BeanWrapper targetWrapper = new BeanWrapperImpl(target);

		for (Method method : sourceInterfaceClazz.getMethods()) {
			if (!isGetter(method)) {
				continue;
			}

			String propertyName = getterToPropertyName(method);

			if (!sourceWrapper.isReadableProperty(propertyName)
					|| !targetWrapper.isWritableProperty(propertyName)) {
				continue;
			}

			Object value = sourceWrapper.getPropertyValue(propertyName);
			if (value != null) {
				targetWrapper.setPropertyValue(propertyName, value);
			}
		}

		return target;
	}

	private static boolean isGetter(Method method) {
		if (method.getParameterCount() != 0 || method.getReturnType() == Void.TYPE) {
			return false;
		}

		String methodName = method.getName();
		return (methodName.startsWith("get") && methodName.length() > 3)
				|| (methodName.startsWith("is")
						&& methodName.length() > 2
						&& (method.getReturnType() == boolean.class
								|| method.getReturnType() == Boolean.class));
	}

	private static String getterToPropertyName(Method getter) {
		String methodName = getter.getName();
		String propertyName = methodName.startsWith("is")
				? methodName.substring(2)
				: methodName.substring(3);

		return Introspector.decapitalize(propertyName);
	}

}

