public @NonNull String summarize() {
    final int maxDisplayedMatches = 5;

    var summary = new StringBuilder();
    summary.append("Explanation of score (%s):\n".formatted(score));
    summary.append("    Constraint matches:\n");

    var constraintMatches = matches();
    if (constraintMatches == null) {
        throw new IllegalArgumentException(
                "The constraint matches must be non-null. " +
                "Maybe use ScoreAnalysisFetchPolicy.FETCH_ALL to request the score analysis");
    }

    if (constraintMatches.isEmpty()) {
        summary.append("        %s: constraint (%s) has no matches.\n"
                .formatted(score().toShortString(), constraintRef().constraintName()));
    } else {
        var sortedConstraintMatches = new java.util.ArrayList<>(constraintMatches);
        sortedConstraintMatches.sort((left, right) -> left.score().compareTo(right.score()));

        summary.append("        %s: constraint (%s) has %s matches:\n"
                .formatted(score().toShortString(), constraintRef().constraintName(), constraintMatches.size()));

        int displayedMatches = Math.min(maxDisplayedMatches, sortedConstraintMatches.size());
        for (int i = 0; i < displayedMatches; i++) {
            var match = sortedConstraintMatches.get(i);
            summary.append("            %s: justified with (%s)\n"
                    .formatted(match.score().toShortString(), match.justification()));
        }

        if (sortedConstraintMatches.size() > maxDisplayedMatches) {
            summary.append("            ...\n");
        }
    }

    return summary.toString();
}

