public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    Objects.requireNonNull(other, "other");

    var differenceMap = new HashMap<ConstraintRef, ConstraintAnalysis<Score_>>();

    constraintMap.forEach((constraintRef, constraintAnalysis) -> {
        var otherConstraintAnalysis = other.constraintMap.get(constraintRef);
        differenceMap.put(constraintRef,
                otherConstraintAnalysis == null
                        ? constraintAnalysis
                        : constraintAnalysis.diff(otherConstraintAnalysis));
    });

    other.constraintMap.forEach((constraintRef, otherConstraintAnalysis) -> {
        if (!constraintMap.containsKey(constraintRef)) {
            differenceMap.put(constraintRef, otherConstraintAnalysis.negate());
        }
    });

    return new ScoreAnalysis<>(
            score.subtract(other.score),
            differenceMap,
            isSolutionInitialized && other.isSolutionInitialized);
}

