public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    var result = Stream.concat(constraintMap.keySet().stream(),
            other.constraintMap.keySet().stream())
            .distinct()
            .flatMap(constraintRef -> {
                var constraintAnalysis = getConstraintAnalysis(constraintRef);
                var otherConstraintAnalysis = other.getConstraintAnalysis(constraintRef);

                var matches = constraintAnalysis.matches();
                var otherMatches = otherConstraintAnalysis.matches();

                boolean hasMatches = matches != null;
                boolean otherHasMatches = otherMatches != null;

                if (hasMatches != otherHasMatches) {
                    throw new IllegalArgumentException(
                            "Score analyses are incompatible: match data is enabled for only one analysis "
                                    + "of constraint " + constraintRef);
                }

                var diff = ConstraintAnalysis.diff(
                        constraintRef,
                        constraintAnalysis,
                        otherConstraintAnalysis);

                boolean hasMeaningfulMatchDifference =
                        diff.matches() != null && !diff.matches().isEmpty();

                // Exclude constraints with no score/weight change and no meaningful
                // match difference. Match data that is absent or unchanged is omitted.
                if (diff.weight().isZero()
                        && diff.score().isZero()
                        && !hasMeaningfulMatchDifference) {
                    return Stream.empty();
                }

                return Stream.of(diff);
            })
            .collect(Collectors.toMap(
                    ConstraintAnalysis::constraintRef,
                    Function.identity(),
                    (existing, replacement) -> existing,
                    HashMap::new));

    return new ScoreAnalysis<>(score.subtract(other.score()), result, isSolutionInitialized);
}

